const item = $input.first().json;
return [{ json: { 
  ok: true, 
  numero_pedido: item.numero_pedido || item.shopify_order_name || 'SIM-OK', 
  total: item.total || 219900, 
  moneda: 'COP', 
  dias_entrega: item.dias_entrega || '1 a 3 días hábiles',
  mensaje: 'Tu pedido ya fue confirmado previamente.'
} }];

const res = $input.first().json || {};
const upd = $('DB Update Simulado Name').first().json;
const val = $('Validar Entrada').first().json;
const pay = $('Construir Payload').first().json;
const env = val.input;
const fecha = new Date().toLocaleString('sv-SE', { timeZone: 'America/Bogota' });
const fila = [
  fecha,
  upd.shopify_order_name,
  (env.nombre + ' ' + (env.apellido || '')).trim(),
  String(env.celular),
  pay.db.ciudad_oficial,
  env.departamento || pay.db.shopify_province_code,
  env.direccion,
  env.barrio + (env.complemento ? ' - ' + env.complemento : '') + (env.referencias ? ' (' + env.referencias + ')' : ''),
  'Combo Taladro Percutor Inalámbrico',
  Number(pay.db.precio_total),
  'Contraentrega'
];
const sinEncabezado = !res.error && !(Array.isArray(res.values) && res.values.length);
const headers = ["Fecha","ID_Pedido","Cliente","Celular","Ciudad","Departamento","Direccion","Barrio","Producto","Total_COP","Metodo_Pago"];
return [{ json: { values: sinEncabezado ? [headers, fila] : [fila] } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
function armarMensaje(d) {
  const texto =
    '🎉 <b>¡NUEVA VENTA CONCRETADA!</b> 🛒\n\n' +
    '🆔 <b>Pedido:</b> <code>' + esc(d.pedido) + '</code>\n' +
    '👤 <b>Cliente:</b> ' + esc(d.cliente) + '\n' +
    '📱 <b>Celular:</b> <a href="https://wa.me/57' + esc(d.celular) + '">' + esc(d.celular) + '</a>\n' +
    '📍 <b>Ciudad:</b> ' + esc(d.ciudad) + ' (' + esc(d.dpto) + ')\n' +
    '🏠 <b>Dirección:</b> ' + esc(d.direccion) + '\n' +
    '🏘️ <b>Barrio:</b> ' + esc(d.barrio) + '\n' +
    '📦 <b>Producto:</b> 1 Combo Taladro Percutor Inalámbrico\n' +
    '💰 <b>Total a Cobrar:</b> $' + esc(d.total) + ' COP (Contraentrega)\n' +
    '🚚 <b>Tiempo Entrega:</b> ' + esc(d.dias) + ' días hábiles';
  return {
    chat_id: d.chat_id,
    text: texto,
    parse_mode: 'HTML',
    reply_markup: { inline_keyboard: [
      [ { text: '📋 Ver Ficha', callback_data: 'ver_' + d.id }, { text: '🚚 Marcar Despachado', callback_data: 'estado_' + d.id + '_despachado' } ],
      [ { text: '❌ Cancelar Pedido', callback_data: 'cancelar_' + d.id } ]
    ] }
  };
}

const upd = $('DB Update Simulado Name').first().json;
const val = $('Validar Entrada').first().json;
